110	        this.numSlackVariables      = getConstraintTypeCounts(Relationship.LEQ) +
111	                                      getConstraintTypeCounts(Relationship.GEQ);
112	        this.numArtificialVariables = getConstraintTypeCounts(Relationship.EQ) +
113	                                      getConstraintTypeCounts(Relationship.GEQ);
114	        this.tableau = new RealMatrixImpl(createTableau(goalType == GoalType.MAXIMIZE));
115	        initialize();
116	    }
117	
118	    /**
119	     * Create the tableau by itself.
120	     * @param maximize if true, goal is to maximize the objective function
121	     * @return created tableau
122	     */
123	    protected double[][] createTableau(final boolean maximize) {
124	
125	        // create a matrix of the correct size
126	        List<LinearConstraint> constraints = getNormalizedConstraints();
127	        int width = numDecisionVariables + numSlackVariables +
128	        numArtificialVariables + getNumObjectiveFunctions() + 1; // + 1 is for RHS
129	        int height = constraints.size() + getNumObjectiveFunctions();
130	        double[][] matrix = new double[height][width];
131	
132	        // initialize the objective function rows
133	        if (getNumObjectiveFunctions() == 2) {
134	            matrix[0][0] = -1;
135	        }
136	        int zIndex = (getNumObjectiveFunctions() == 1) ? 0 : 1;
137	        matrix[zIndex][zIndex] = maximize ? 1 : -1;
138	        RealVector objectiveCoefficients =
139	            maximize ? f.getCoefficients().mapMultiply(-1) : f.getCoefficients();
140	            copyArray(objectiveCoefficients.getData(), matrix[zIndex], getNumObjectiveFunctions());
141	            matrix[zIndex][width - 1] =
142	                maximize ? f.getConstantTerm() : -1 * f.getConstantTerm();
143	
144	                if (!restrictToNonNegative) {
145	                    matrix[zIndex][getSlackVariableOffset() - 1] =
146	                        getInvertedCoeffiecientSum(objectiveCoefficients);
147	                }
148	
149	                // initialize the constraint rows
150	                int slackVar = 0;
151	                int artificialVar = 0;
152	                for (int i = 0; i < constraints.size(); i++) {
153	                    LinearConstraint constraint = constraints.get(i);
154	                    int row = getNumObjectiveFunctions() + i;
155	
156	                    // decision variable coefficients
157	                    copyArray(constraint.getCoefficients().getData(), matrix[row], 1);
158	
159	                    // x-
160	                    if (!restrictToNonNegative) {
161	                        matrix[row][getSlackVariableOffset() - 1] =
162	                            getInvertedCoeffiecientSum(constraint.getCoefficients());
163	                    }
164	
165	                    // RHS
166	                    matrix[row][width - 1] = constraint.getValue();
167	
168	                    // slack variables
169	                    if (constraint.getRelationship() == Relationship.LEQ) {
170	                        matrix[row][getSlackVariableOffset() + slackVar++] = 1;  // slack
171	                    } else if (constraint.getRelationship() == Relationship.GEQ) {
172	                        matrix[row][getSlackVariableOffset() + slackVar++] = -1; // excess
173	                    }
174	
175	                    // artificial variables
176	                    if ((constraint.getRelationship() == Relationship.EQ) ||
177	                        (constraint.getRelationship() == Relationship.GEQ)) {
178	                        matrix[0][getArtificialVariableOffset() + artificialVar] = 1; 
179	                        matrix[row][getArtificialVariableOffset() + artificialVar++] = 1; 
180	                    }
181	                }
182	
183	                return matrix;
184	    }
185	
186	    /** Get the number of variables.
187	     * @return number of variables
188	     */
189	    public int getNumVariables() {
190	        return f.getCoefficients().getDimension();
191	    }
192	
193	    /**
194	     * Get new versions of the constraints which have positive right hand sides.
195	     * @return new versions of the constraints
196	     */
197	    public List<LinearConstraint> getNormalizedConstraints() {
198	        List<LinearConstraint> normalized = new ArrayList<LinearConstraint>();
199	        for (LinearConstraint constraint : constraints) {
200	            normalized.add(normalize(constraint));
201	        }
202	        return normalized;
203	    }
204	
205	    /**
206	     * Get a new equation equivalent to this one with a positive right hand side.
207	     * @param constraint reference constraint
208	     * @return new equation
209	     */
210	    private LinearConstraint normalize(final LinearConstraint constraint) {
211	        if (constraint.getValue() < 0) {
212	            return new LinearConstraint(constraint.getCoefficients().mapMultiply(-1),
213	                                        constraint.getRelationship().oppositeRelationship(),
214	                                        -1 * constraint.getValue());
215	        }
216	        return new LinearConstraint(constraint.getCoefficients(), 
217	                                    constraint.getRelationship(), constraint.getValue());
218	    }
219	
220	    /**
221	     * Get the number of objective functions in this tableau.
222	     * @return 2 for Phase 1.  1 for Phase 2.
223	     */
224	    protected final int getNumObjectiveFunctions() {
225	        return this.numArtificialVariables > 0 ? 2 : 1;
226	    }
227	
228	    /**
229	     * Get a count of constraints corresponding to a specified relationship.
230	     * @param relationship relationship to count
231	     * @return number of constraint with the specified relationship
232	     */
233	    private int getConstraintTypeCounts(final Relationship relationship) {
234	        int count = 0;
235	        for (final LinearConstraint constraint : constraints) {
236	            if (constraint.getRelationship() == relationship) {
237	                ++count;
238	            }
239	        }
240	        return count;
241	    }
242	
243	    /**
244	     * Puts the tableau in proper form by zeroing out the artificial variables
245	     * in the objective function via elementary row operations.
246	     */
247	    private void initialize() {
248	        for (int artificialVar = 0; artificialVar < numArtificialVariables; artificialVar++) {
249	            int row = getBasicRow(getArtificialVariableOffset() + artificialVar);
250	            subtractRow(0, row, 1.0);
251	        }
252	    }
253	
254	    /**
255	     * Get the -1 times the sum of all coefficients in the given array.
256	     * @param coefficients coefficients to sum
257	     * @return the -1 times the sum of all coefficients in the given array.
258	     */
259	    protected static double getInvertedCoeffiecientSum(final RealVector coefficients) {
260	        double sum = 0;
261	        for (double coefficient : coefficients.getData()) {
262	            sum -= coefficient;
263	        }
264	        return sum;
265	    }
266	
267	    /**
268	     * Checks whether the given column is basic.
269	     * @param col index of the column to check
270	     * @return the row that the variable is basic in.  null if the column is not basic
271	     */
272	    private Integer getBasicRow(final int col) {
273	        Integer row = null;
274	        for (int i = getNumObjectiveFunctions(); i < getHeight(); i++) {
275	            if (!MathUtils.equals(getEntry(i, col), 0.0, epsilon)) {
276	                if (row == null) {
277	                    row = i;
278	                } else {
279	                    return null;
280	                }
281	            }
282	        }
283	        return row;
284	    }
285	
286	    /**
287	     * Removes the phase 1 objective function and artificial variables from this tableau.
288	     */
289	    protected void discardArtificialVariables() {
290	        if (numArtificialVariables == 0) {
291	            return;
292	        }
293	        int width = getWidth() - numArtificialVariables - 1;
294	        int height = getHeight() - 1;
295	        double[][] matrix = new double[height][width];
296	        for (int i = 0; i < height; i++) {
297	            for (int j = 0; j < width - 1; j++) {
298	                matrix[i][j] = getEntry(i + 1, j + 1);
299	            }
300	            matrix[i][width - 1] = getEntry(i + 1, getRhsOffset());
301	        }
302	        this.tableau = new RealMatrixImpl(matrix);
303	        this.numArtificialVariables = 0;
304	    }
305	
306	
307	    /**
308	     * @param src the source array
309	     * @param dest the destination array
310	     * @param destPos the destination position
311	     */
312	    private void copyArray(final double[] src, final double[] dest,
313	                           final int destPos) {
314	        System.arraycopy(src, 0, dest, getNumObjectiveFunctions(), src.length); 
315	    }
316	
317	    /**
318	     * Get the current solution.
319	     * <p>
320	     * {@link #solve} should be called first for this to be the optimal solution.
321	     * </p>
322	     * @return current solution
323	     */
324	    protected RealPointValuePair getSolution() {
325	        double[] coefficients = new double[getOriginalNumDecisionVariables()];
326	        Integer basicRow =
327	            getBasicRow(getNumObjectiveFunctions() + getOriginalNumDecisionVariables());
328	        double mostNegative = basicRow == null ? 0 : getEntry(basicRow, getRhsOffset());
329	        for (int i = 0; i < coefficients.length; i++) {
330	            basicRow = getBasicRow(getNumObjectiveFunctions() + i);
331	                // if multiple variables can take a given value 
332	                // then we choose the first and set the rest equal to 0
333	                coefficients[i] =
334	                    (basicRow == null ? 0 : getEntry(basicRow, getRhsOffset())) -
335	                    (restrictToNonNegative ? 0 : mostNegative);
336	            if (basicRow != null) {
337	                for (int j = getNumObjectiveFunctions(); j < getNumObjectiveFunctions() + i; j++) {
338	                    if (tableau.getEntry(basicRow, j) == 1) {
339	                         coefficients[i] = 0;
340	                    }
341	                }
342	            }
343	        }
344	        return new RealPointValuePair(coefficients, f.getValue(coefficients));
345	    }
346	
347	    /**
348	     * Subtracts a multiple of one row from another.
349	     * <p>
350	     * After application of this operation, the following will hold:
351	     *   minuendRow = minuendRow - multiple * subtrahendRow
352	     * </p>
353	     * @param dividendRow index of the row
354	     * @param divisor value of the divisor
355	     */
356	    protected void divideRow(final int dividendRow, final double divisor) {
357	        for (int j = 0; j < getWidth(); j++) {
358	            tableau.setEntry(dividendRow, j, tableau.getEntry(dividendRow, j) / divisor);
359	        }
360	    }
361	
362	    /**
363	     * Subtracts a multiple of one row from another.
364	     * <p>
365	     * After application of this operation, the following will hold:
366	     *   minuendRow = minuendRow - multiple * subtrahendRow
367	     * </p>
368	     * @param minuendRow row index
369	     * @param subtrahendRow row index
370	     * @param multiple multiplication factor
371	     */
372	    protected void subtractRow(final int minuendRow, final int subtrahendRow,
373	                               final double multiple) {
374	        for (int j = 0; j < getWidth(); j++) {
375	            tableau.setEntry(minuendRow, j, tableau.getEntry(minuendRow, j) -
376	                             multiple * tableau.getEntry(subtrahendRow, j));
377	        }
378	    }
379	
380	    /**
381	     * Get the width of the tableau.
382	     * @return width of the tableau
383	     */
384	    protected final int getWidth() {
385	        return tableau.getColumnDimension();
386	    }
387	
388	    /**
389	     * Get the height of the tableau.
390	     * @return height of the tableau
391	     */
392	    protected final int getHeight() {
393	        return tableau.getRowDimension();
394	    }
395	
396	    /** Get an entry of the tableau.
397	     * @param row row index
398	     * @param column column index
399	     * @return entry at (row, column)
400	     */
401	    protected final double getEntry(final int row, final int column) {
402	        return tableau.getEntry(row, column);
403	    }
404	
405	    /** Set an entry of the tableau.
406	     * @param row row index
407	     * @param column column index
408	     * @param value for the entry
409	     */
410	    protected final void setEntry(final int row, final int column,
411	                                  final double value) {
412	        tableau.setEntry(row, column, value);
413	    }
414	
415	    /**
416	     * Get the offset of the first slack variable.
417	     * @return offset of the first slack variable
418	     */
419	    protected final int getSlackVariableOffset() {
420	        return getNumObjectiveFunctions() + numDecisionVariables;
421	    }
422	
423	    /**
424	     * Get the offset of the first artificial variable.
425	     * @return offset of the first artificial variable
426	     */
427	    protected final int getArtificialVariableOffset() {
428	        return getNumObjectiveFunctions() + numDecisionVariables + numSlackVariables;
429	    }
430	
431	    /**
432	     * Get the offset of the right hand side.
433	     * @return offset of the right hand side
434	     */
435	    protected final int getRhsOffset() {
436	        return getWidth() - 1;
437	    }
438	
439	    /**
440	     * Get the number of decision variables.
441	     * <p>
442	     * If variables are not restricted to positive values, this will include 1
443	     * extra decision variable to represent the absolute value of the most
444	     * negative variable.
445	     * </p>
446	     * @return number of decision variables
447	     * @see #getOriginalNumDecisionVariables()
448	     */
449	    protected final int getNumDecisionVariables() {
450	        return numDecisionVariables;
451	    }
452	
453	    /**
454	     * Get the original number of decision variables.
455	     * @return original number of decision variables
456	     * @see #getNumDecisionVariables()
457	     */
458	    protected final int getOriginalNumDecisionVariables() {
459	        return restrictToNonNegative ? numDecisionVariables : numDecisionVariables - 1;
460	    }
461	
462	    /**
463	     * Get the number of slack variables.
464	     * @return number of slack variables
465	     */
466	    protected final int getNumSlackVariables() {
467	        return numSlackVariables;
468	    }
469	
470	    /**
471	     * Get the number of artificial variables.
472	     * @return number of artificial variables
473	     */
474	    protected final int getNumArtificialVariables() {
475	        return numArtificialVariables;
476	    }
477	
478	    /**
479	     * Get the tableau data.
480	     * @return tableau data
481	     */
482	    protected final double[][] getData() {
483	        return tableau.getData();
484	    }
485	
486	    /** {@inheritDoc} */
487	    @Override
488	    public boolean equals(Object other) {
489	
490	      if (this == other) { 
491	        return true;
492	      }
493	
494	      if (other == null) {
495	        return false;
496	      }
497	
498	      try {
499	
500	          SimplexTableau rhs = (SimplexTableau) other;
501	          return (restrictToNonNegative  == rhs.restrictToNonNegative) &&
502	                 (numDecisionVariables   == rhs.numDecisionVariables) &&
503	                 (numSlackVariables      == rhs.numSlackVariables) &&
504	                 (numArtificialVariables == rhs.numArtificialVariables) &&
505	                 (epsilon                == rhs.epsilon) &&
506	                 f.equals(rhs.f) &&
507	                 constraints.equals(rhs.constraints) &&
508	                 tableau.equals(rhs.tableau);
509	
510	      } catch (ClassCastException ex) {
511	          // ignore exception
512	          return false;
513	      }
514	
515	    }
516	    
517	    /** {@inheritDoc} */
518	    @Override
519	    public int hashCode() {
520	        return Boolean.valueOf(restrictToNonNegative).hashCode() ^
521	               numDecisionVariables ^
522	               numSlackVariables ^
523	               numArtificialVariables ^
524	               Double.valueOf(epsilon).hashCode() ^
525	               f.hashCode() ^
526	               constraints.hashCode() ^
527	               tableau.hashCode();
528	    }
529	
530	    /** Serialize the instance.
531	     * @param oos stream where object should be written
532	     * @throws IOException if object cannot be written to stream
533	     */
534	    private void writeObject(ObjectOutputStream oos)
535	        throws IOException {
536	        oos.defaultWriteObject();
537	        MatrixUtils.serializeRealMatrix(tableau, oos);
538	    }
539	
540	    /** Deserialize the instance.
541	     * @param ois stream from which the object should be read
542	     * @throws ClassNotFoundException if a class in the stream cannot be found
543	     * @throws IOException if object cannot be read from the stream
544	     */
545	    private void readObject(ObjectInputStream ois)
546	      throws ClassNotFoundException, IOException {
547	        ois.defaultReadObject();
548	        MatrixUtils.deserializeRealMatrix(this, "tableau", ois);
549	    }
550	}
